-- Esquema de Centro Comercial Colonial. Ejecutar en Supabase SQL Editor.
create extension if not exists pgcrypto;
create table if not exists public.admins (user_id uuid primary key references auth.users(id) on delete cascade, email text not null, creado timestamptz not null default now());
create or replace function public.es_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.admins where user_id=auth.uid()); $$;
create table if not exists public.categorias (id uuid primary key default gen_random_uuid(), slug text unique not null, nombre text not null, descripcion text, imagen text, orden int not null default 0, visible boolean not null default true);
create table if not exists public.productos (id uuid primary key default gen_random_uuid(), slug text unique not null, nombre text not null, descripcion text, precio numeric(12,2) not null check(precio>=0), precio_oferta numeric(12,2) check(precio_oferta is null or precio_oferta>=0), stock int not null default 0 check(stock>=0), categoria_id uuid references public.categorias(id) on delete set null, imagenes text[] not null default '{}', colores text[] not null default '{}', tallas text[] not null default '{}', destacado boolean not null default false, visible boolean not null default true, orden int not null default 0, creado timestamptz not null default now(), actualizado timestamptz not null default now());
create table if not exists public.pedidos (id uuid primary key default gen_random_uuid(), codigo text unique not null default upper(substr(encode(gen_random_bytes(5),'hex'),1,8)), cliente_nombre text not null, cliente_telefono text not null, cliente_email text, direccion text, notas text, items jsonb not null default '[]', total numeric(12,2) not null check(total>=0), estado text not null default 'nuevo' check(estado in ('nuevo','confirmado','enviado','entregado','cancelado')), creado timestamptz not null default now());
create table if not exists public.ajustes (clave text primary key, valor jsonb not null default '{}'::jsonb);
create or replace function public.actualizar_fecha_producto() returns trigger language plpgsql as $$ begin new.actualizado=now(); return new; end; $$;
drop trigger if exists trg_productos_actualizado on public.productos;
create trigger trg_productos_actualizado before update on public.productos for each row execute function public.actualizar_fecha_producto();
alter table public.admins enable row level security; alter table public.categorias enable row level security; alter table public.productos enable row level security; alter table public.pedidos enable row level security; alter table public.ajustes enable row level security;
drop policy if exists "admins leen su registro" on public.admins; create policy "admins leen su registro" on public.admins for select to authenticated using(user_id=auth.uid());
drop policy if exists "categorias publicas visibles" on public.categorias; create policy "categorias publicas visibles" on public.categorias for select to anon,authenticated using(visible or public.es_admin());
drop policy if exists "admins gestionan categorias" on public.categorias; create policy "admins gestionan categorias" on public.categorias for all to authenticated using(public.es_admin()) with check(public.es_admin());
drop policy if exists "productos publicos visibles" on public.productos; create policy "productos publicos visibles" on public.productos for select to anon,authenticated using(visible or public.es_admin());
drop policy if exists "admins gestionan productos" on public.productos; create policy "admins gestionan productos" on public.productos for all to authenticated using(public.es_admin()) with check(public.es_admin());
drop policy if exists "clientes crean pedidos" on public.pedidos; create policy "clientes crean pedidos" on public.pedidos for insert to anon,authenticated with check(estado='nuevo');
drop policy if exists "admins leen pedidos" on public.pedidos; create policy "admins leen pedidos" on public.pedidos for select to authenticated using(public.es_admin());
drop policy if exists "admins actualizan pedidos" on public.pedidos; create policy "admins actualizan pedidos" on public.pedidos for update to authenticated using(public.es_admin()) with check(public.es_admin());
drop policy if exists "ajustes publicos lectura" on public.ajustes; create policy "ajustes publicos lectura" on public.ajustes for select to anon,authenticated using(true);
drop policy if exists "admins gestionan ajustes" on public.ajustes; create policy "admins gestionan ajustes" on public.ajustes for all to authenticated using(public.es_admin()) with check(public.es_admin());
insert into storage.buckets(id,name,public,file_size_limit,allowed_mime_types) values('productos','productos',true,5242880,array['image/jpeg','image/png','image/webp']) on conflict(id) do nothing;
drop policy if exists "imagenes productos publicas" on storage.objects; create policy "imagenes productos publicas" on storage.objects for select to anon,authenticated using(bucket_id='productos');
drop policy if exists "admins suben imagenes" on storage.objects; create policy "admins suben imagenes" on storage.objects for insert to authenticated with check(bucket_id='productos' and public.es_admin());
drop policy if exists "admins actualizan imagenes" on storage.objects; create policy "admins actualizan imagenes" on storage.objects for update to authenticated using(bucket_id='productos' and public.es_admin()) with check(bucket_id='productos' and public.es_admin());
drop policy if exists "admins eliminan imagenes" on storage.objects; create policy "admins eliminan imagenes" on storage.objects for delete to authenticated using(bucket_id='productos' and public.es_admin());
